import {runtimeConfig} from './runtime-config.js';
import {routeHref,routePath} from './location.js';
import {blank,newItem,collections,clone,uid,apps,validate,compatible,copyModules} from './domain.js';
import {initialProgress,conditionMet} from './engine-v3.js';
import {seed} from './seed.js';
import {Phone} from './player.js';
import {trialAssets,putTrialAsset,hideTrialAsset,promoteTrialDocument} from './trial-assets.js';
import {api,localRead,trialKey,prepareImage} from './services.js';
import {esc,image,button,field,select,check,options,toast} from './ui.js';
const $=s=>document.querySelector(s),app=$('#app'),modal=$('#modal');
const names={phone:'手机与桌面',characters:'人物',rooms:'KakaoTalk 聊天',messages:'消息',replyNodes:'回复节点',albums:'相簿',photos:'照片',notes:'备忘录',sms:'信息',safari:'Safari',calls:'电话与来电',events:'剧情事件',endings:'结局',assets:'素材库',debug:'试玩调试'};
const labels={text:'文字',image:'图片',voice:'语音',gift:'礼物',transfer:'转账'};
let trials=localRead(trialKey,null);if(!Array.isArray(trials))trials=[{id:uid('trial'),document:seed(),trial:true,archived:false}];
let user=null,projects=[],current=null,story=null,section='phone',selectedId='',phone=null,mode='edit',activeTab='preview',undoStack=[],redoStack=[],saveTimer=null,dirty=false,saving=false,saveAgain=false,frozen=false,saveMessage='',libraryAssets=[],libraryCharacters=[],assetTarget=null,dragged=null,focusSender='',transaction=null,reader=false;
let channel;try{channel=new BroadcastChannel('pocket-trials');channel.onmessage=()=>{if(current?.trial){frozen=true;saveMessage='另一标签页修改了试用作品；本页已停止编辑，请刷新核对。';renderStatus();}};}catch{}
function persistTrials(){try{localStorage.setItem(trialKey,JSON.stringify(trials));channel?.postMessage('changed');}catch{throw Error('本机试用存储失败，请释放空间；当前修改仍保留在内存中。');}}
function dialog(title,body,actions=button('关闭','close-modal')){modal.innerHTML=`<header><h2>${title}</h2>${button('×','close-modal','icon-button','aria-label="关闭"')}</header><div class="dialog-body">${body}</div><footer>${actions}</footer>`;if(!modal.open)modal.showModal();}
function closeDialog(){modal.close();assetTarget=null;}
function setRoute(route){history.pushState({},'',routeHref(route));}
function selected(){return Array.isArray(story?.[section])?story[section].find(x=>x.id===selectedId):null;}
function titleOf(x){return x?.name||x?.title||x?.text?.slice(0,24)||x?.keyword||x?.sender||'未命名';}
function allItems(){return collections.flatMap(k=>story[k].map(x=>({...x,kind:k})));}
function choices(k,empty=true){return [...(empty?[['','未选择']]:[]),...story[k].map(x=>[x.id,titleOf(x)])];}
function contentChoices(){return [['','未选择'],...allItems().map(x=>[x.id,`${names[x.kind]} · ${titleOf(x)}`])];}
function getPath(obj,path){return path.split('.').reduce((o,k)=>o?.[k],obj);}
function setPath(obj,path,value){const keys=path.split('.');for(const k of keys.slice(0,-1)){obj[k]??={};obj=obj[k];}obj[keys.at(-1)]=value;}
function remember(){undoStack.push(clone(story));if(undoStack.length>70)undoStack.shift();redoStack=[];}
function canEdit(){return mode==='edit'&&!frozen&&(!current||current.trial||navigator.onLine);}
function mutate(fn,{render=true,history=true}={}){if(!canEdit()){toast('当前无法编辑。请先恢复连接并处理保存错误。');return;}if(history)remember();fn();dirty=true;saveMessage=current.trial?'试用修改待本机保存':'修改尚未保存';clearTimeout(saveTimer);saveTimer=setTimeout(save,650);if(render)renderEditor();else {renderStatus();updatePhone();}}
async function save(){clearTimeout(saveTimer);if(!dirty||!current)return;if(saving){saveAgain=true;return;}if(!current.trial&&!navigator.onLine){frozen=true;saveMessage='网络中断，在线编辑已停止；内存中仍有未保存修改';renderStatus();return;}
 saving=true;saveMessage=current.trial?'保存试用作品…':'正在保存到服务端…';renderStatus();const sent=clone(story),projectAtSave=current;
 try{if(current.trial){current.document=sent;const index=trials.findIndex(p=>p.id===current.id);trials[index]=current;persistTrials();}else{const result=await api('projects/'+current.id,{method:'PUT',body:{revision:current.revision,document:sent}});projectAtSave.revision=result.revision;projectAtSave.document=sent;}
  if(projectAtSave===current&&JSON.stringify(sent)===JSON.stringify(story)){dirty=false;saveMessage=current.trial?'试用已暂存本机':'在线保存成功 · 修订 '+current.revision;}else saveAgain=true;
 }catch(e){frozen=true;saveMessage='未保存 · '+e.message;current.saveConflict=e.status===409;toast(saveMessage);}finally{saving=false;renderStatus();if(saveAgain&&!frozen){saveAgain=false;await save();}}
}
function renderStatus(){const el=$('#save-status');if(el)el.textContent=saveMessage;const title=$('.studio-top strong');if(title&&story)title.textContent=story.title;const form=$('#properties');if(form){form.disabled=!canEdit();form.classList.toggle('disabled',!canEdit());}const banner=$('#offline-banner');if(banner){banner.classList.toggle('visible',frozen);banner.innerHTML=esc(saveMessage)+' '+button(current?.saveConflict?'核对修订冲突':'恢复连接后重试保存',current?.saveConflict?'resolve-conflict':'retry-save');}}
function selectItem(kind,id){if(kind==='add-message'){add('messages',id);return;}section=kind;selectedId=id;activeTab='properties';renderEditor();const prefix={rooms:'room',messages:'room',characters:'profile',notes:'note',sms:'sms',safari:'result',albums:'album'}[kind];if(prefix){phone.page=prefix+':'+(kind==='messages'?selected().roomId:id);phone.render();}}
function updatePhone(){if(!phone||mode!=='edit')return;phone.story=story;phone.focusSender=focusSender;phone.render();}
function mountPhone(progress){phone?.destroy();phone=new Phone({story,mode,progress,onSelect:selectItem,onProgress:p=>{if(reader){try{localStorage.setItem('pocket-reader-'+current.publicId,JSON.stringify(p));}catch{toast('이 기기에서 진행 상황을 저장할 수 없습니다.');}}},onDebug:p=>{if($('#debug-output'))$('#debug-output').innerHTML=debugHtml(p);}});phone.focusSender=focusSender;phone.mount($('#phone-mount'));}
async function openProject(p){if(dirty){await save();if(dirty){toast('当前作品尚未保存，请先处理保存状态。');return;}}current=p;story=clone(p.document);undoStack=[];redoStack=[];frozen=false;dirty=false;section='phone';selectedId='';mode='edit';saveMessage=p.trial?'本机试用 · 登录后可选择转入账号':'在线草稿 · 修订 '+p.revision;setRoute('/studio/projects/'+p.id);renderEditor();}
function library(){phone?.destroy();phone=null;current=null;story=null;mode='edit';setRoute('/studio');app.className='';const list=user?projects:trials;
 app.innerHTML=`<div class="library"><nav class="global-nav"><a href="${routeHref('/studio')}" class="wordmark">◧ 口袋叙事 <span>STORY STUDIO</span></a><div>${user?`<small>${esc(user.email)}</small>${button('人物库','shared-characters')}${button('素材库','shared-assets')}${button('退出','logout')}`:button('邮箱验证码登录','login','primary')}</div></nav><main>${runtimeConfig.hosting==='github-pages'&&!runtimeConfig.apiBase?'<p class="notice">网站页面已可访问，但正式在线服务尚未连接。当前编辑仅为本机试用，不能在线保存或发布。</p>':''}<div class="library-heading"><div><small class="eyebrow">A WORLD BEHIND THE SCREEN</small><h1>每一部手机，<br>都有未说完的故事。</h1><p>从一句消息、一张照片，编织可以被探索的世界。</p></div><div class="new-actions">${button('＋ 直接创建','new-direct','primary')}${button('引导创建','new-guided')}</div></div><div class="library-section"><h2>${user?'我的在线作品':'我的试用作品'}</h2><span>${user?'草稿与发布版本独立保存':'多部试用暂存当前浏览器；在线保存和发布需要登录'}</span></div><div class="project-grid">${list.map(p=>`<article class="project-card ${p.archived?'archived':''}"><div class="project-art"><div class="mini-phone">◧<span>${esc(p.document.title.slice(0,1))}</span></div><span class="project-badge">${p.archived?'已归档':p.trial?'本机试用':p.online?'已上线':'在线草稿'}</span></div><div class="project-info"><h3>${esc(p.document.title)}</h3><small>${p.document.characters.length} 位人物 · ${p.document.events.length} 个事件</small><div class="project-actions">${button('继续创作','open-project','primary','data-id="'+p.id+'"')}${button('•••','project-menu','','data-id="'+p.id+'"')}</div></div></article>`).join('')}<button class="empty-project" data-action="new-direct"><span>＋</span>开始一个新世界</button></div><p class="library-note">固定 iPhone 18 Pro 模板 · 七个应用 · 创作者手填中韩对照</p></main></div>`;
}
function renderEditor(progressOverride=null){if(!story)return;const oldPage=phone?.page,oldProgress=progressOverride||phone?.p;if(reader)return;app.className=mode==='play'?'playing':'';
 app.innerHTML=`<div class="studio"><header class="studio-top"><div>${button('‹ 作品库','library','subtle')}<span class="divider-v"></span><strong>${esc(story.title)}</strong><span class="draft-tag">${current.trial?'本机试用':'在线草稿'}</span></div><div><small id="save-status">${esc(saveMessage)}</small>${button('撤销','undo','','aria-label="撤销" '+(!undoStack.length?'disabled':''))}${button('重做','redo','','aria-label="重做" '+(!redoStack.length?'disabled':''))}${button(mode==='play'?'返回编辑':'从头试玩',mode==='play'?'edit':'play')}${button('发布与版本','publish','primary')}</div></header><div id="offline-banner" class="offline-banner ${frozen?'visible':''}">${esc(saveMessage)} ${button(current.saveConflict?'核对修订冲突':'恢复连接后重试保存',current.saveConflict?'resolve-conflict':'retry-save')}</div><nav class="mobile-editor-tabs">${button('目录','mobile-directory')}${button('手机预览','mobile-preview')}${button('属性','mobile-properties')}</nav><aside class="directory ${activeTab==='directory'?'mobile-active':''}"><div class="directory-heading"><b>创作目录</b><small>CONTENTS</small></div><div class="module-list">${Object.entries(names).filter(([k])=>k!=='messages'&&k!=='debug').map(([k,n])=>`<button class="module ${section===k?'active':''}" data-action="section" data-kind="${k}"><span>${({phone:'◧',characters:'♙',rooms:'☏',replyNodes:'↳',albums:'▧',photos:'✿',notes:'▤',sms:'▰',safari:'◈',calls:'☎',events:'⋈',endings:'⚑',assets:'▢'})[k]}</span>${n}<small>${story[k]?.length??''}</small></button>`).join('')}</div><div class="directory-items">${directoryItems()}</div><div class="directory-foot">${button('节点试玩与调试','debug-setup')}${button('检查剧情引用','validate')}</div></aside><main class="canvas ${activeTab==='preview'?'mobile-active':''}"><div class="canvas-heading"><div><small>${mode==='play'?'独立测试进度':'实时预览'}</small><h1>${esc(names[section]||'创作工作台')}</h1></div><span>iPhone 18 Pro</span></div><div class="canvas-stage" style="background:${/^#[\da-f]{6}$/i.test(story.phone.outer)?story.phone.outer:'#e9e9ed'}"><div id="phone-mount"></div></div><div class="canvas-caption">${mode==='edit'?'点击手机中的内容，在右侧编辑属性':'试玩进度独立，不会改变作品初始状态或读者存档'}</div></main><aside class="properties ${activeTab==='properties'?'mobile-active':''}"><header><b>${mode==='play'?'试玩调试':'属性编辑'}</b><small>PROPERTIES</small></header>${mode==='play'?`<div id="debug-output">${debugHtml(oldProgress||initialProgress(story))}</div>`:`<fieldset id="properties" ${canEdit()?'':'disabled'}>${inspector()}</fieldset>`}</aside></div>`;
 mountPhone(mode==='play'?oldProgress:undefined);if(oldPage&&mode==='edit'){phone.page=oldPage;phone.render();}renderStatus();setupDrag();
}
function directoryItems(){if(section==='phone')return '<div class="directory-intro"><small>固定模板</small><h3>iPhone 18 Pro</h3><p>深色机身，独立锁屏与桌面。应用外观固定，顺序由你安排。</p></div>';if(section==='assets')return '<p class="muted">共享素材跨作品复用。隐藏素材不会破坏发布内容。</p>'+button('打开素材库','shared-assets');const items=story[section]||[];return `<div class="list-heading">${names[section]} <span>${items.length}</span></div>${items.map(x=>`<button draggable="true" class="content-row ${x.id===selectedId?'active':''}" data-action="select-item" data-kind="${section}" data-id="${x.id}">${section==='photos'?image(x.src):''}<span>${esc(titleOf(x))}</span><small data-reorder-handle>⠿</small></button>`).join('')}${button('＋ 添加'+(names[section]||'内容'),'add-item','add-row')}`;}
function common(item){return `<div class="property-actions">${button('复制','duplicate-item')}${button('删除','delete-item','danger')}</div><small class="stable-id">ID · ${esc(item.id)}</small>`;}
function visibilityFields(item){return check('初始可见','initial',item.initial!==false)+select('未解锁时','lockedStyle',item.lockedStyle||'hidden',[['hidden','完全隐藏'],['placeholder','锁定占位']]);}
function mediaField(label,key,value){return `<label>${label}</label><div class="media-value">${image(value)}${value?`<small>${esc(value.split('/').slice(-2).join('/'))}</small>`:'<small>尚未选择素材</small>'}${button(value?'替换素材':'选择素材','pick-asset','','data-target="'+key+'"')}${value?button('清除','clear-media','','data-target="'+key+'"'):''}</div>`;}
function multi(label,key,pairs,values){return `<label>${label}</label><div class="multi-list">${pairs.map(([id,name])=>`<label class="check"><input type="checkbox" data-multi="${key}" value="${esc(id)}" ${(values||[]).includes(id)?'checked':''}>${esc(name)}</label>`).join('')}</div>`;}
function cropFields(label,prefix){const crop=getPath(story.phone,prefix)||{x:50,y:50,scale:1};return `<details><summary>${label} · 拖动与缩放裁切</summary><div class="crop-preview" data-crop="${prefix}" style="${phone?.wallpaper(story.phone[prefix==='lockCrop'?'lockWallpaper':'wallpaper'],crop)||''}"><span>手机 / 电脑预览</span></div>${field('水平位置',`phone.${prefix}.x`,crop.x,'range','min="0" max="100"')}${field('垂直位置',`phone.${prefix}.y`,crop.y,'range','min="0" max="100"')}${field('放大比例',`phone.${prefix}.scale`,crop.scale,'range','min="1" max="4" step="0.05"')}</details>`;}
function inspector(){const item=selected();
 if(section==='phone')return `<div class="property-title"><small>PHONE SETTINGS</small><h2>故事，从一部手机开始</h2></div>${field('作品名称','story.title',story.title)}${select('手机主人','phone.ownerId',story.phone.ownerId,choices('characters'))}<p class="hint">先创建人物，再从已有的人物中指定主人。</p>${field('锁屏密码（留空则无密码）','phone.passcode',story.phone.passcode,'text','inputmode="numeric" maxlength="6"')}${field('密码提示（留空隐藏）','phone.hint',story.phone.hint)}${check('记住手机解锁','phone.remember',story.phone.remember)}${mediaField('锁屏壁纸','phone.lockWallpaper',story.phone.lockWallpaper)}${cropFields('锁屏','lockCrop')}${mediaField('桌面壁纸','phone.wallpaper',story.phone.wallpaper)}${cropFields('桌面','homeCrop')}${field('手机外背景','phone.outer',story.phone.outer,'color')}${field('电量','phone.battery',story.phone.battery,'number','min="0" max="100"')}${field('信号格数','phone.signal',story.phone.signal,'number','min="0" max="4"')}${select('网络类型','phone.network',story.phone.network,[['5G','5G'],['LTE','LTE'],['Wi-Fi','Wi-Fi']])}${check('显示天气组件','phone.weather',story.phone.weather)}${field('天气内容','phone.weatherText',story.phone.weatherText)}${check('显示日期组件','phone.dateWidget',story.phone.dateWidget)}${field('网格列数','phone.columns',story.phone.columns,'number','min="2" max="6"')}${field('图标大小','phone.iconSize',story.phone.iconSize,'number','min="36" max="68"')}${field('每页数量','phone.pageSize',story.phone.pageSize,'number','min="1" max="24"')}<label>桌面应用顺序 · 拖动排序</label><div class="order-list">${story.phone.appOrder.map(id=>`<div draggable="true" data-order="apps" data-id="${id}"><span data-reorder-handle>⠿</span> ${apps.find(x=>x[0]===id)?.[1]}</div>`).join('')}</div>${multi('隐藏应用','phone.hiddenApps',apps.map(a=>[a[0],a[1]]),story.phone.hiddenApps)}${multi('Dock（最多四个，按勾选顺序）','phone.dock',apps.map(a=>[a[0],a[1]]),story.phone.dock)}${check('KakaoTalk 手填中韩对照','phone.bilingual',story.phone.bilingual)}${check('中文对照默认展开','phone.translationOpen',story.phone.translationOpen)}${select('自动打字速度','phone.typingSpeed',story.phone.typingSpeed,[['slow','慢'],['normal','正常'],['fast','快']])}${select('进入作品计时起点','phone.timerStart',story.phone.timerStart,[['lock','锁屏出现'],['unlock','首次解锁']])}${mediaField('作品统一消息提示音','phone.messageSound',story.phone.messageSound)+check('相册提供保存图片按钮','phone.savePhotos',story.phone.savePhotos)}${select('相机预设照片','phone.cameraPhotoId',story.phone.cameraPhotoId,choices('photos'))}${check('重新开始时重置密码记忆','phone.resetPasswords',story.phone.resetPasswords)}${field('进度兼容版本','story.compatibilityVersion',story.compatibilityVersion,'number','min="1"')}<p class="hint">结构变化时提升兼容版本。无法完整兼容的旧进度会要求重新开始。</p>`;
 if(section==='assets')return `<h2>账号素材库</h2><p class="muted">图片、头像、语音与铃声可跨作品复用。正式素材需要登录后在线上传。</p>${button('管理素材','shared-assets','primary')}`;
 if(!item)return `<h2>${esc(names[section])}</h2><p class="muted">从目录选择一项，或添加新的内容。</p>${button('＋ 添加','add-item','primary')}`;
 const top=`<div class="property-title"><small>${section.toUpperCase()}</small><h2>${esc(titleOf(item))}</h2></div>`;
 if(section==='characters')return top+field('人物本名','name',item.name)+field('当前手机联系人备注','remark',item.remark)+field('状态文字','status',item.status)+mediaField('头像','avatar',item.avatar)+mediaField('资料背景','background',item.background)+`<details><summary>资料背景裁切</summary>${field('水平位置','crop.x',item.crop.x,'range','min="0" max="100"')}${field('垂直位置','crop.y',item.crop.y,'range','min="0" max="100"')}${field('缩放比例','crop.scale',item.crop.scale,'range','min="1" max="4" step="0.05"')}</details><label>个人资料册 · 拖动排序</label><div class="profile-assets">${item.gallery.map((src,i)=>`<div draggable="true" data-order="gallery" data-id="${i}"><span data-reorder-handle>⠿</span>${image(src)}${button('×','remove-gallery','','data-index="'+i+'"')}</div>`).join('')}</div>`+button('＋ 添加资料图片','pick-asset','','data-target="gallery"')+check('显示资料页聊天按钮','chatButton',item.chatButton)+check('显示资料页电话按钮','phoneButton',item.phoneButton)+select('聊天按钮解锁开关（留空无锁）','chatGate',item.chatGate||'',[['','无锁'],...Object.keys(story.switches).map(k=>[k,k])])+select('电话按钮解锁开关（留空无锁）','phoneGate',item.phoneGate||'',[['','无锁'],...Object.keys(story.switches).map(k=>[k,k])])+select('电话按钮行为','phoneMode',item.phoneMode,[['unavailable','不可用'],['call','拨出预设通话'],['event','触发事件']])+(item.phoneMode==='call'?select('通话脚本','callId',item.callId,choices('calls')):item.phoneMode==='event'?select('触发事件','eventId',item.eventId,choices('events')):'')+button('保存到共享人物库','save-character','full')+common(item);
 if(section==='rooms')return top+field('聊天名称','name',item.name)+check('群聊','group',item.group)+(item.group?multi('群成员','members',choices('characters',false),item.members):select('单聊人物','characterId',item.characterId,choices('characters')))+mediaField('群头像（留空拼接成员头像）','avatar',item.avatar)+check('置顶聊天','pinned',item.pinned)+field('起始故事时间','startTime',item.startTime,'datetime-local')+field('默认消息间隔（秒）','interval',item.interval,'number','min="0"')+select('突出并用于新增消息的人物','ui.focusSender',focusSender,choices('characters'))+`<label>逐条消息</label><div class="message-editor-list">${story.messages.filter(m=>m.roomId===item.id).map(m=>`<button draggable="true" data-order="messages" data-id="${m.id}" data-action="select-item" data-kind="messages"><span data-reorder-handle>⠿</span> ${esc(story.characters.find(c=>c.id===m.sender)?.name)} · ${esc(m.type==='text'?m.text:labels[m.type])}</button>`).join('')}</div>`+button('＋ 添加消息','add-message','primary','data-room="'+item.id+'"')+select('回复节点','replyMode',item.replyMode,[['readonly','只读'],['preset','点击预设回复'],['typing','自动打字发送预设台词'],['free','自由输入任意内容']])+(item.replyMode!=='readonly'?field('预设韩文回复','replyText',item.replyText,'textarea')+field('手填中文对照','replyZh',item.replyZh,'textarea')+select('发送后触发事件','replyEventId',item.replyEventId,choices('events'))+check('将回复显示为主人消息','replyAsMessage',item.replyAsMessage):'')+common(item);
 if(section==='replyNodes')return top+field('节点名称','name',item.name)+select('所属聊天','roomId',item.roomId,choices('rooms'))+select('在此消息到达后出现（留空立即）','afterMessageId',item.afterMessageId,[['','立即'],...story.messages.filter(m=>m.roomId===item.roomId).map(m=>[m.id,m.text||labels[m.type]])])+select('解锁开关（留空无锁）','gateSwitch',item.gateSwitch,[['','无锁'],...Object.keys(story.switches).map(k=>[k,k])])+select('回复方式','replyMode',item.replyMode,[['readonly','只读'],['preset','点击预设回复'],['typing','自动打字'],['free','自由输入']])+field('预设韩文台词','replyText',item.replyText,'textarea')+field('手填中文对照','replyZh',item.replyZh,'textarea')+select('触发事件','replyEventId',item.replyEventId,choices('events'))+check('发送主人消息','replyAsMessage',item.replyAsMessage)+common(item);
 if(section==='messages'){const index=story.messages.indexOf(item);return top+select('所属聊天','roomId',item.roomId,choices('rooms'))+select('发送者','sender',item.sender,choices('characters'))+select('消息类型','type',item.type,Object.entries(labels))+field('故事显示时间','time',item.time,'time')+(item.type==='text'?field('韩文原文 / 普通正文','text',item.text,'textarea')+field('手填中文对照','zh',item.zh,'textarea'):item.type==='image'?mediaField('聊天图片','src',item.src):item.type==='voice'?mediaField('语音音频','audio',item.audio)+field('文字稿','transcript',item.transcript,'textarea')+check('文字稿默认展开','transcriptOpen',item.transcriptOpen):item.type==='gift'?field('商品名','product',item.product)+field('赠言','text',item.text,'textarea')+mediaField('商品图','src',item.src):field('金额','amount',item.amount)+field('赠言','text',item.text)+check('已收款（否则待收款）','received',item.received))+select('引用同聊已出现的消息','quoteId',item.quoteId,[['','不引用'],...story.messages.slice(0,index).filter(m=>m.roomId===item.roomId).map(m=>[m.id,m.text||labels[m.type]])])+check('显示发送失败（仅展示）','failed',item.failed)+check('作为初始历史消息','initial',item.initial)+button('返回聊天属性','back-room','full')+common(item);}
 if(section==='photos')return top+field('创作端识别名称（读者不显示）','title',item.title)+mediaField('照片','src',item.src)+visibilityFields(item)+select('照片剧情判定','trigger',item.trigger,[['display','大图显示（含左右切换）'],['grid','网格点击'],['zoom','放大查看']])+multi('所属相簿（同一照片身份）','ui.photoAlbums',choices('albums',false),story.albums.filter(a=>a.photoIds.includes(item.id)).map(a=>a.id))+common(item);
 if(section==='albums')return top+field('相簿名','name',item.name)+mediaField('相簿封面','cover',item.cover)+visibilityFields(item)+multi('收录照片','photoIds',choices('photos',false),item.photoIds)+`<label>照片顺序 · 拖动排序</label><div class="order-list">${item.photoIds.map(id=>`<div draggable="true" data-order="albumPhotos" data-id="${id}"><span data-reorder-handle>⠿</span> ${esc(titleOf(story.photos.find(x=>x.id===id)))}</div>`).join('')}</div>`+common(item);
 if(section==='notes')return top+field('标题','title',item.title)+field('正文','text',item.text,'textarea')+field('故事日期','date',item.date,'date')+visibilityFields(item)+field('独立密码（4 / 6 位，留空无密码）','passcode',item.passcode,'text','inputmode="numeric" maxlength="6"')+check('记住正确密码后的解锁','remember',item.remember)+field('密码提示','hint',item.hint)+field('错误文案','error',item.error)+field('重试次数','attempts',item.attempts,'number','min="1"')+select('次数用尽后','exhaustion',item.exhaustion,[['cooldown','冷却后重试'],['disabled','本次阅读禁用密码输入']])+field('冷却秒数','cooldown',item.cooldown,'number','min="0"')+common(item);
 if(section==='sms')return top+field('号码 / 机构名称','sender',item.sender)+field('历史短信正文','text',item.text,'textarea')+field('故事日期','date',item.date,'date')+'<p class="hint">信息为初始历史记录，只读且不触发剧情。</p>'+common(item);
 if(section==='safari')return top+field('预设搜索关键词','keyword',item.keyword)+field('结果标题','title',item.title)+mediaField('一张结果图片','src',item.src)+common(item);
 if(section==='calls')return top+field('显示名称 / 陌生号码','name',item.name)+select('关联人物（可不选）','characterId',item.characterId,choices('characters'))+field('通话文字稿','text',item.text,'textarea')+mediaField('通话音频','audio',item.audio)+mediaField('此通来电铃声','ringtone',item.ringtone)+select('来电呈现','presentation',item.presentation,[['fullscreen','全屏'],['banner','顶部横幅']])+field('等待接听秒数','timeout',item.timeout,'number','min="1"')+select('离开后过期处理','expired',item.expired,[['replay','返回时排队补显示'],['missed','记为未接并推进']])+select('拒接 / 超时 / 挂断后触发','afterEventId',item.afterEventId,choices('events'))+'<p class="hint">接听后仅由读者主动挂断，音频结束不会挂断。</p>'+common(item);
 if(section==='endings')return top+field('结局名称','title',item.title)+field('结局正文','text',item.text,'textarea')+mediaField('结局图片','src',item.src)+mediaField('结局音乐','audio',item.audio)+check('允许继续浏览已解锁内容','continue',item.continue)+field('继续按钮文案','button',item.button)+common(item);
 if(section==='events')return top+eventInspector(item)+common(item);
 return top;
}
const conditionTypes=[['chat.enter','进入聊天'],['message.read','指定消息进入可见区域'],['attachment.read','查看指定聊天附件'],['chat.complete','读完聊天当前全部消息'],['photo.grid','照片网格点击'],['photo.display','照片大图显示'],['photo.zoom','照片放大'],['note.attempt','尝试打开备忘录'],['note.read','已读备忘录正文'],['safari.read','查看 Safari 记录'],['reply','完成聊天回复'],['call.end','通话已结束 / 未接'],['switch','布尔开关'],['unlocked','内容已解锁']];
const actionTypes=[['send','发送聊天消息'],['notify','通知'],['unlock','解锁内容'],['note.unlock','解除备忘录密码'],['call','来电'],['wait','等待'],['ending','结局'],['hide','隐藏内容'],['character','修改人物资料'],['wallpaper','切换桌面壁纸'],['set','修改布尔开关'],['member.add','群成员加入'],['member.remove','群成员退出']];
function eventInspector(e){return field('事件名称','name',e.name)+check('启用','enabled',e.enabled)+select('当……','trigger',e.trigger,[['state','条件状态达成'],['start','进入作品'],['delay','进入后延迟'],['manual','被回复 / 通话 / 其他入口调用'],...conditionTypes.filter(x=>!['switch','unlocked'].includes(x[0]))])+(['delay'].includes(e.trigger)?field('延迟毫秒','delay',e.delay||0,'number','min="0"'):!['state','start','manual'].includes(e.trigger)?select('触发内容','target',e.target,contentChoices()):'')+select('满足……','conditionMode',e.conditionMode,[['all','全部条件（无顺序要求）'],['any','任一条件']])+`<div class="event-blocks">${e.conditions.map((c,i)=>`<section><header>条件 ${i+1}${button('×','remove-condition','','data-index="'+i+'"')}</header><label>条件类型<select data-condition="${i}:type">${options(conditionTypes,c.type)}</select></label>${c.type==='switch'?`<label>开关<select data-condition="${i}:key">${options(Object.keys(story.switches).map(k=>[k,k]),c.key)}</select></label><label>值<select data-condition="${i}:value">${options([['true','开启'],['false','关闭']],String(c.value))}</select></label>`:`<label>内容<select data-condition="${i}:target">${options(contentChoices(),c.target)}</select></label>`}</section>`).join('')}</div>`+button('＋ 添加条件','add-condition','full')+`<label>就……按顺序执行（可拖动）</label><div class="event-blocks">${e.actions.map((a,i)=>`<section draggable="true" data-order="actions" data-id="${i}"><header><span data-reorder-handle>⠿</span> 动作 ${i+1}${button('×','remove-action','','data-index="'+i+'"')}</header><label>动作<select data-event-action="${i}:type">${options(actionTypes,a.type)}</select></label>${actionFields(a,i)}</section>`).join('')}</div>`+button('＋ 添加动作','add-action','full')+check('允许重复','repeat',e.repeat)+(e.repeat?field('执行上限','maxRuns',e.maxRuns,'number','min="1"')+field('重复间隔毫秒','interval',e.interval,'number','min="100"'):'')+select('补演后的后续动作计时','timing',e.timing,[['actual','按实际补演时间'],['scheduled','按原定现实时间']])+`<hr><h3>作品布尔开关</h3>${Object.entries(story.switches).map(([key,value])=>check(esc(key),'switches.'+key,value)).join('')}${button('＋ 新增开关','add-switch')}`;}
function actionFields(a,i){const f=(label,key,value,type='text')=>`<label>${label}<input type="${type}" data-event-action="${i}:${key}" value="${esc(value)}"></label>`,sel=(label,key,value,pairs)=>`<label>${label}<select data-event-action="${i}:${key}">${options(pairs,value)}</select></label>`;if(a.type==='wait')return f('毫秒','ms',a.ms||0,'number');if(a.type==='set')return sel('开关','key',a.key,Object.keys(story.switches).map(k=>[k,k]))+sel('值','value',String(a.value),[['true','开启'],['false','关闭']]);if(a.type==='wallpaper')return `<label>壁纸素材</label>${image(a.src)}${button('选择素材','pick-asset','','data-target="actions.'+i+'.src"')}`;let pairs=a.type==='call'?choices('calls'):a.type==='ending'?choices('endings'):a.type==='send'?choices('messages'):a.type==='note.unlock'?choices('notes'):a.type==='character'?choices('characters'):a.type.startsWith('member.')?choices('rooms'):contentChoices();let html=sel('目标','target',a.target||'',pairs);if(a.type==='notify')html=f('标题','title',a.title)+f('正文','text',a.text)+html+f('停留毫秒（0 为一直显示）','duration',a.duration||0,'number');if(a.type.startsWith('member.'))html+=sel('成员','characterId',a.characterId||'',choices('characters'));if(a.type==='character')html+=sel('字段','field',a.field||'status',[['name','姓名'],['remark','备注'],['status','状态文字']])+f('新值','value',a.value);return html;}
function add(kind=section,roomId){if(!collections.includes(kind))return;mutate(()=>{const x=newItem(kind,story);if(kind==='messages'){const r=story.rooms.find(r=>r.id===roomId)||story.rooms[0];if(!r){toast('请先创建聊天');return;}x.roomId=r.id;x.sender=focusSender||r.characterId||story.phone.ownerId;const previous=story.messages.filter(m=>m.roomId===r.id).at(-1);const date=new Date(r.startTime);if(previous){const [h,m]=previous.time.split(':').map(Number);date.setHours(h,m+(r.interval||0)/60);}x.time=date.toTimeString().slice(0,5);}story[kind].push(x);if(kind==='characters'&&!story.phone.ownerId)story.phone.ownerId=x.id;if(kind==='photos')story.recentOrder.push(x.id);section=kind;selectedId=x.id;activeTab='properties';});}
function debugHtml(p){return `<div class="debug-panel"><h3>条件与任务</h3><p>此进度仅用于试玩</p><div class="debug-counts"><span>待执行 ${p.pending.length}</span><span>排队来电 ${p.callQueue.length}</span></div><h4>布尔开关</h4>${Object.entries(p.variables).map(([k,v])=>`<p>${esc(k)} = ${v}</p>`).join('')}<h4>事件条件</h4>${story.events.map(e=>`<div class="debug-event"><b>${esc(e.name)}</b><small>已执行 ${p.eventCounts[e.id]||0} 次</small>${e.conditions.map(c=>`<p>${conditionMet(c,p)?'●':'○'} ${esc(conditionTypes.find(x=>x[0]===c.type)?.[1])} · ${esc(c.target||c.key)}</p>`).join('')}</div>`).join('')}<h4>待执行任务</h4>${p.pending.map(t=>`<p>${esc(t.action.type)} · ${new Date(t.due).toLocaleTimeString()}</p>`).join('')}<h4>运行记录</h4>${p.log.slice(-35).reverse().map(l=>`<p class="log-line"><small>${new Date(l.at).toLocaleTimeString()}</small>${esc(l.text)}</p>`).join('')}</div>`;}
function debugSetup(){dialog('节点试玩与模拟状态',`<p>手动选择模拟条件，不会自动补齐或改变作品初始状态。</p><label>起始页面<select id="test-page">${options([['lock','锁屏'],['home','桌面'],...story.rooms.map(x=>['room:'+x.id,'聊天 · '+x.name]),...story.photos.map(x=>['photo:'+x.id,'照片 · '+x.title]),...story.events.map(x=>['event:'+x.id,'事件 · '+x.name])],'lock')}</select></label>${multi('模拟已读消息','test.read',choices('messages',false),[])}${multi('模拟事件中的阅读 / 打开条件','test.facts',[...new Map(story.events.flatMap(e=>e.conditions).filter(c=>!['switch','unlocked'].includes(c.type)).map(c=>[c.type+':'+c.target,[c.type+':'+c.target,(conditionTypes.find(t=>t[0]===c.type)?.[1]||c.type)+' · '+titleOf(allItems().find(x=>x.id===c.target))]])).values()],[])}${multi('模拟解锁内容','test.unlocked',contentChoices().slice(1),[])}${multi('模拟已开启开关','test.switch',Object.keys(story.switches).map(k=>[k,k]),[])}`,button('取消','close-modal')+button('开始节点试玩','debug-start','primary'));}
async function showAssets(target){assetTarget=target||null;try{libraryAssets=user?await api('assets'):await trialAssets();}catch(e){toast(e.message);return;}dialog(target?'选择素材':'账号素材库',`${!user?'<p class="notice">试用素材仅暂存本机；登录转入作品时会上传其引用素材。</p>':''}${`<label class="check"><input type="checkbox" id="compress-images" checked>压缩图片（保留真实比例）</label><label class="upload-zone">＋ 上传图片 / 音频<input id="asset-file" type="file" accept="image/png,image/jpeg,image/webp,image/gif,audio/*"></label><p id="upload-status" class="hint"></p>`}<div class="asset-grid">${[...libraryAssets,...['station','sea','room'].map(k=>({id:k,name:'原创示例 · '+k,url:'/assets/'+k+'.svg',mime:'image/svg+xml'}))].map(a=>`<article>${a.mime.startsWith('image/')?image(a.url):'<div class="audio-thumb">♫</div>'}<b>${esc(a.name)}</b><small>${a.size?`${(a.original_size/1024).toFixed(1)} → ${(a.size/1024).toFixed(1)} KB`: '原创插画'}</small>${target?button('使用','use-asset','','data-src="'+a.url+'"'):''}${libraryAssets.includes(a)?button('引用 / 隐藏','asset-menu','','data-id="'+a.id+'"'):''}</article>`).join('')}</div>`);assetTarget=target;}
async function showCharacters(){if(!user){dialog('共享人物库','<p>个人共享人物库需要邮箱登录。作品内人物仍可在试用中完整编辑。</p>',button('关闭','close-modal')+button('登录','login','primary'));return;}libraryCharacters=await api('characters');dialog('个人共享人物库',`<p>导入作品后为独立副本，后续修改不会联动。</p><div class="character-library">${libraryCharacters.map(c=>`<article>${image(c.avatar)}<b>${esc(c.name)}</b><small>${esc(c.status)}</small>${story?button('导入当前作品','import-character','','data-id="'+c.id+'"'):''}${button('编辑','edit-shared-character','','data-id="'+c.id+'"')}${button('删除','delete-shared-character','danger','data-id="'+c.id+'"')}</article>`).join('')||'<p>还没有共享人物。可从作品人物属性保存一份。</p>'}</div>`,button('新建共享人物','new-shared-character','primary')+button('关闭','close-modal'));}
function login(){dialog('邮箱验证码登录',`<p>正式草稿与素材在线保存。验证码发送到你的邮箱，不设置密码。</p><label>邮箱<input type="email" id="login-email" autocomplete="email" placeholder="you@example.com"></label><div id="verification-fields"></div><p class="error" id="login-error"></p>`,button('取消','close-modal')+button('发送验证码','request-code','primary'));}
async function reloadProjects(){if(user)projects=await api('projects');}
function selectTrialImport(){if(!trials.length)return;dialog('选择转入账号的试用作品',`<p>只转入勾选的作品。转入成功后，本机试用原件仍保留。</p>${trials.map(p=>`<label class="check"><input type="checkbox" name="import-trial" value="${p.id}">${esc(p.document.title)}</label>`).join('')}`,button('暂不转入','close-modal')+button('在线保存所选作品','import-trials','primary'));}
async function publishDialog(){if(!current)return;await save();if(dirty){toast('还有未保存内容，暂不能发布。');return;}if(current.trial){dialog('发布需要邮箱登录','<p>当前作品仅为本机试用，尚未在线发布。登录后选择转入账号，再生成真实阅读链接。</p>',button('关闭','close-modal')+button('登录并选择转入','login','primary'));return;}const versions=await api('projects/'+current.id+'/versions');dialog('发布与版本',`<p>发布生成不可变快照，草稿修改不会影响在线版。读者下次打开或刷新才读取新版。</p><p>${current.liveVersion?`稳定阅读入口：<a href="${routeHref('/read/'+current.publicId)}" target="_blank">打开阅读链接</a> · ${current.online?'已上线':'已下线'}`:'尚未发布，无可读链接'}</p><label>更新失败时<select id="failure-policy"><option value="keep">保留旧版</option><option value="offline">暂时下线</option></select></label><label class="check"><input type="checkbox" id="optional-check">发布前执行可选剧情引用检查</label><h3>已发布版本</h3>${versions.map(v=>`<div class="version-row"><b>版本 ${v.number}</b><small>${new Date(v.created).toLocaleString()}</small></div>`).join('')||'<p class="muted">还没有发布版本</p>'}`,button('关闭','close-modal')+(current.liveVersion?button(current.online?'暂时下线':'重新上线','toggle-online'):'')+button('发布冻结版本','publish-now','primary'));}
function newProjectDialog(guided){dialog(guided?'引导创建作品':'直接创建',field('作品名称','new.title','未命名作品')+(guided?field('手机主人姓名','new.owner','')+field('锁屏密码（可留空）','new.passcode','','text','inputmode="numeric" maxlength="6"'):'')+`<label class="check"><input id="new-demo" type="checkbox">使用原创示例内容</label>`,button('取消','close-modal')+button('开始创作','create-project','primary','data-guided="'+guided+'"'));}
function moduleCopyDialog(p){dialog('选择复制模块',`<p>复制生成独立草稿与新阅读标识。事件模块会连同其依赖内容一起复制。</p>${collections.map(k=>`<label class="check"><input type="checkbox" name="copy-module" value="${k}" checked>${names[k]}</label>`).join('')}`,button('取消','close-modal')+button('创建副本','copy-project','primary','data-id="'+p.id+'"'));}
function projectMenu(p){dialog(esc(p.document.title),`<p>${p.trial?'本机试用作品':'在线作品'} · ${p.archived?'已归档':'未归档'}</p>`,button('关闭','close-modal')+button('勾选模块复制','copy-dialog','','data-id="'+p.id+'"')+button(p.archived?'恢复归档':'归档','archive-dialog','','data-id="'+p.id+'"')+button('删除作品','delete-project-dialog','danger','data-id="'+p.id+'"'));}
function setupDrag(){const root=app;root.ondragstart=e=>{const el=e.target.closest('[draggable="true"]');if(el)dragged={id:el.dataset.id||el.dataset.appId,order:el.dataset.order|| (el.dataset.appId?'apps':'collection'),kind:el.dataset.kind||section};};root.ondragover=e=>{if(e.target.closest('[draggable="true"]'))e.preventDefault();};root.ondrop=e=>{e.preventDefault();const target=e.target.closest('[draggable="true"]');if(!target||!dragged)return;const d=dragged;dragged=null;mutate(()=>{const order=d.order;const array=order==='apps'?story.phone.appOrder:order==='gallery'?selected().gallery:order==='albumPhotos'?selected().photoIds:order==='actions'?selected().actions:order==='messages'?story.messages:story[d.kind];const from=order==='gallery'||order==='actions'?Number(d.id):array.findIndex(x=>(typeof x==='string'?x:x.id)===d.id);const targetId=target.dataset.id||target.dataset.appId;const to=order==='gallery'||order==='actions'?Number(targetId):array.findIndex(x=>(typeof x==='string'?x:x.id)===targetId);if(from<0||to<0)return;array.splice(to,0,array.splice(from,1)[0]);if(d.kind==='photos')story.recentOrder=story.photos.map(x=>x.id);});};}
let cropDrag=null;
document.addEventListener('pointerdown',e=>{const el=e.target.closest('[data-crop]');if(!el||!canEdit())return;remember();cropDrag={el,key:el.dataset.crop,x:e.clientX,y:e.clientY,crop:clone(story.phone[el.dataset.crop]||{x:50,y:50,scale:1})};el.setPointerCapture(e.pointerId);});
document.addEventListener('pointermove',e=>{if(!cropDrag)return;const d=cropDrag,crop={...d.crop,x:Math.max(0,Math.min(100,d.crop.x+(e.clientX-d.x)/2)),y:Math.max(0,Math.min(100,d.crop.y+(e.clientY-d.y)/3))};story.phone[d.key]=crop;d.el.style.backgroundPosition=`${crop.x}% ${crop.y}%`;updatePhone();});
document.addEventListener('pointerup',()=>{if(cropDrag){cropDrag=null;dirty=true;saveMessage='裁切修改尚未保存';clearTimeout(saveTimer);saveTimer=setTimeout(save,650);renderStatus();}});
document.addEventListener('focusin',e=>{if(e.target.matches('[data-field]')&&!modal.contains(e.target))transaction=e.target;});
document.addEventListener('input',e=>{const x=e.target;if(!x.dataset.field||modal.contains(x)||x.type==='checkbox'||x.tagName==='SELECT')return;if(!canEdit())return;const first=transaction===x;if(first)transaction=null;applyField(x,first,false);});
document.addEventListener('change',e=>{const x=e.target;if(x.id==='asset-file'){uploadAsset(x.files?.[0]);return;}if(modal.contains(x))return;if(x.dataset.field&&(x.type==='checkbox'||x.tagName==='SELECT')){applyField(x,true,true);return;}if(x.dataset.multi){const key=x.dataset.multi,id=x.value;mutate(()=>{if(key==='ui.photoAlbums'){for(const a of story.albums){const has=a.photoIds.includes(selectedId);if(a.id===id&&x.checked&&!has)a.photoIds.push(selectedId);if(a.id===id&&!x.checked)a.photoIds=a.photoIds.filter(v=>v!==selectedId);}return;}const object=key.startsWith('phone.')?story.phone:selected(),prop=key.replace('phone.',''),array=object[prop];if(x.checked){if(key==='phone.dock'&&array.length>=4){toast('Dock 最多四个应用');return;}if(!array.includes(id))array.push(id);}else object[prop]=array.filter(v=>v!==id);});return;}if(x.dataset.condition||x.dataset.eventAction){mutate(()=>{const [i,k]=(x.dataset.condition||x.dataset.eventAction).split(':'),a=x.dataset.condition?selected().conditions[i]:selected().actions[i];if(k==='type'){if(x.dataset.condition)selected().conditions[i]={type:x.value,target:'',key:Object.keys(story.switches)[0]||'',value:true};else selected().actions[i]={type:x.value,target:'',key:Object.keys(story.switches)[0]||'',value:true,ms:1000,field:'status'};}else a[k]=['ms','duration'].includes(k)?Number(x.value):k==='value'&&['switch','set'].includes(a.type)?x.value==='true':x.value;});}});
function applyField(x,history,render){const key=x.dataset.field;mutate(()=>{const value=x.type==='checkbox'?x.checked:['number','range'].includes(x.type)?Number(x.value):x.value;if(key==='ui.focusSender'){focusSender=value;return;}if(key.startsWith('switches.')){story.switches[key.slice(9)]=value;return;}if(key.startsWith('phone.'))setPath(story.phone,key.slice(6),value);else if(key.startsWith('story.'))setPath(story,key.slice(6),value);else setPath(selected(),key,value);},{history,render});}
async function uploadAsset(file){if(!file)return;const el=$('#upload-status');try{if(el)el.textContent='正在处理…';const blob=await prepareImage(file,$('#compress-images')?.checked);if(el)el.textContent=`${(file.size/1024).toFixed(1)} → ${(blob.size/1024).toFixed(1)} KB · 上传中`;if(!user)await putTrialAsset(blob,file.size,file.name);else await api('assets',{method:'POST',body:blob,headers:{'Content-Type':blob.type,'X-File-Name':encodeURIComponent(file.name),'X-Original-Size':String(file.size)}});await showAssets(assetTarget);toast(`上传完成：${(file.size/1024).toFixed(1)} → ${(blob.size/1024).toFixed(1)} KB`);}catch(e){if(el)el.textContent='处理或上传失败：'+e.message;}}
let challengeId=null;
document.addEventListener('click',async e=>{const x=e.target.closest('[data-action]');if(!x||x.dataset.action.startsWith('phone.'))return;const a=x.dataset.action,id=x.dataset.id;try{
 if(a==='close-modal')closeDialog();
 if(a==='login'){closeDialog();login();}
 if(a==='request-code'){x.disabled=true;try{const response=await api('auth/request',{method:'POST',body:{email:$('#login-email').value}});challengeId=response.challengeId;$('#verification-fields').innerHTML='<label>六位验证码<input id="login-code" inputmode="numeric" autocomplete="one-time-code" maxlength="6"></label>';modal.querySelector('footer').innerHTML=button('验证并登录','verify-code','primary');$('#login-error').textContent='验证码已发送，请检查邮箱。';}catch(err){$('#login-error').textContent=err.message;x.disabled=false;}}
 if(a==='verify-code'){x.disabled=true;try{const result=await api('auth/verify',{method:'POST',body:{challengeId,code:$('#login-code').value}});user=result.user;closeDialog();await reloadProjects();library();selectTrialImport();}catch(err){$('#login-error').textContent=err.message;x.disabled=false;}}
 if(a==='logout'){await save();if(dirty)return;await api('auth/logout',{method:'POST'});user=null;library();}
 if(a==='import-trials'){const ids=[...modal.querySelectorAll('[name="import-trial"]:checked')].map(x=>x.value);x.disabled=true;for(const tid of ids){const p=trials.find(p=>p.id===tid);await api('projects',{method:'POST',body:{document:await promoteTrialDocument(p.document,api)}});}closeDialog();await reloadProjects();library();toast('所选作品已在线保存');}
 if(a==='library'){await save();if(dirty)return;await reloadProjects();library();}
 if(a==='new-direct'||a==='new-guided')newProjectDialog(a==='new-guided');
 if(a==='create-project'){const title=modal.querySelector('[data-field="new.title"]').value.trim();if(!title)throw Error('请填写作品名称');const doc=$('#new-demo').checked?seed():blank(title);doc.title=title;if(x.dataset.guided==='true'){const name=modal.querySelector('[data-field="new.owner"]').value.trim();const pass=modal.querySelector('[data-field="new.passcode"]').value;if(pass&&!/^\d{4}(\d{2})?$/.test(pass))throw Error('密码为 4 或 6 位数字');if(name){const c=newItem('characters',doc);c.name=name;doc.characters.push(c);doc.phone.ownerId=c.id;}doc.phone.passcode=pass;}let p;if(user)p=await api('projects',{method:'POST',body:{document:doc}});else{p={id:uid('trial'),document:doc,trial:true,archived:false};trials.push(p);persistTrials();}closeDialog();await openProject(p);}
 if(a==='open-project')await openProject((user?projects:trials).find(p=>p.id===id));
 if(a==='project-menu')projectMenu((user?projects:trials).find(p=>p.id===id));
 if(a==='copy-dialog')moduleCopyDialog((user?projects:trials).find(p=>p.id===id));
 if(a==='copy-project'){const p=(user?projects:trials).find(p=>p.id===id),modules=[...modal.querySelectorAll('[name="copy-module"]:checked')].map(x=>x.value);if(p.trial){trials.push({id:uid('trial'),document:copyModules(p.document,modules),trial:true,archived:false});persistTrials();}else await api('projects/'+id+'/copy',{method:'POST',body:{modules}});closeDialog();await reloadProjects();library();}
 if(a==='archive-dialog'){const p=(user?projects:trials).find(p=>p.id===id);dialog(p.archived?'恢复归档':'归档作品',`<p>归档后仍可恢复。</p>${p.online?'<label class="check"><input type="checkbox" id="take-offline">同时下线公开阅读链接</label>':''}`,button('取消','close-modal')+button('确认','archive-project','primary','data-id="'+id+'"'));}
 if(a==='archive-project'){const p=(user?projects:trials).find(p=>p.id===id);if(p.trial){p.archived=!p.archived;persistTrials();}else await api('projects/'+id+'/state',{method:'POST',body:{archived:!p.archived,...($('#take-offline')?.checked?{online:false}:{})}});closeDialog();await reloadProjects();library();}
 if(a==='delete-project-dialog'){const p=(user?projects:trials).find(p=>p.id===id);dialog('删除作品不可恢复',`<p>确定删除「${esc(p.document.title)}」的创作草稿？</p>${p.online?'<label class="check"><input type="checkbox" id="delete-offline" checked>同时下线公开阅读链接</label>':'<p>该作品当前没有在线阅读入口。</p>'}`,button('取消','close-modal')+button('永久删除草稿','delete-project','danger','data-id="'+id+'"'));}
 if(a==='delete-project'){const p=(user?projects:trials).find(p=>p.id===id);if(p.trial){trials=trials.filter(p=>p.id!==id);persistTrials();}else await api('projects/'+id,{method:'DELETE',body:{takeOffline:$('#delete-offline')?.checked??true}});closeDialog();await reloadProjects();library();}
 if(a==='section'){section=x.dataset.kind;selectedId=story[section]?.[0]?.id||'';activeTab='directory';if(section==='assets')showAssets();renderEditor();const page={phone:'home',characters:'friends',rooms:'chat',albums:'albums',photos:'photos',notes:'notes',sms:'sms',safari:'safari',calls:'calls'}[section];if(page)phone.navigate(page);}
 if(a==='select-item'){selectItem(x.dataset.kind,id);const prefix={characters:'profile',rooms:'room',messages:'room',albums:'album',notes:'note',sms:'sms',safari:'result'}[section];if(prefix)phone.navigate(prefix+':'+(section==='messages'?selected().roomId:id));}
 if(a==='add-item')add();if(a==='add-message')add('messages',x.dataset.room||selected()?.id);
 if(a==='back-room'){const room=selected().roomId;selectItem('rooms',room);}
 if(a==='duplicate-item')mutate(()=>{const item=clone(selected());item.id=uid(section);story[section].push(item);selectedId=item.id;});
 if(a==='delete-item'){const item=selected();dialog('删除内容',`<p>确认删除「${esc(titleOf(item))}」？引用该内容的剧情需要随后核对。</p>`,button('取消','close-modal')+button('删除','confirm-delete-item','danger'));}
 if(a==='confirm-delete-item'){closeDialog();mutate(()=>{const id=selectedId;story[section]=story[section].filter(x=>x.id!==id);if(section==='photos'){story.recentOrder=story.recentOrder.filter(x=>x!==id);story.albums.forEach(a=>a.photoIds=a.photoIds.filter(x=>x!==id));}if(section==='rooms')story.messages=story.messages.filter(m=>m.roomId!==id);selectedId=story[section][0]?.id||'';});}
 if(a==='undo'||a==='redo'){const source=a==='undo'?undoStack:redoStack,target=a==='undo'?redoStack:undoStack;if(source.length&&canEdit()){target.push(clone(story));story=source.pop();dirty=true;clearTimeout(saveTimer);saveTimer=setTimeout(save,650);renderEditor();}}
 if(a==='play'){await save();phone?.destroy();phone=null;mode='play';activeTab='preview';renderEditor();}
 if(a==='edit'){phone?.destroy();phone=null;mode='edit';renderEditor();}
 if(a==='mobile-directory'||a==='mobile-preview'||a==='mobile-properties'){activeTab=a.slice(7);document.querySelectorAll('.directory,.canvas,.properties').forEach(el=>el.classList.toggle('mobile-active',el.classList.contains({directory:'directory',preview:'canvas',properties:'properties'}[activeTab])));}
 if(a==='resolve-conflict'){const latest=await api('projects/'+current.id);current.conflictLatest=latest;dialog('核对两份草稿',`<p>本页修改仍在内存中，服务端版本没有被覆盖。</p><table class="conflict-table"><tr><th>内容</th><th>本页未保存</th><th>服务端修订 ${latest.revision}</th></tr><tr><td>名称</td><td>${esc(story.title)}</td><td>${esc(latest.document.title)}</td></tr>${collections.map(k=>'<tr><td>'+names[k]+'</td><td>'+story[k].length+' 项</td><td>'+latest.document[k].length+' 项</td></tr>').join('')}</table><p>保存为独立作品会保留两份；加载服务端版本将放弃本页未保存修改。</p>`,button('继续保留本页','close-modal')+button('加载服务端版本','conflict-load')+button('保存本页为独立作品','conflict-copy','primary'));}
 if(a==='conflict-load'){const latest=current.conflictLatest;closeDialog();dirty=false;frozen=false;phone?.destroy();phone=null;current=latest;story=clone(latest.document);undoStack=[];redoStack=[];saveMessage='已加载服务端修订 '+latest.revision;renderEditor();}
 if(a==='conflict-copy'){const created=await api('projects',{method:'POST',body:{document:{...clone(story),id:uid('story'),title:story.title+' · 冲突副本'}}});closeDialog();dirty=false;frozen=false;phone?.destroy();phone=null;await openProject(created);}
 if(a==='retry-save'){if(!navigator.onLine)throw Error('网络仍未恢复');frozen=false;await save();renderStatus();}
 if(a==='add-condition')mutate(()=>selected().conditions.push({type:'chat.enter',target:story.rooms[0]?.id||''}));
 if(a==='remove-condition')mutate(()=>selected().conditions.splice(Number(x.dataset.index),1));
 if(a==='add-action')mutate(()=>selected().actions.push({type:'wait',ms:1000}));
 if(a==='remove-action')mutate(()=>selected().actions.splice(Number(x.dataset.index),1));
 if(a==='add-switch'){dialog('新增布尔开关','<label>开关名称<input id="switch-name" placeholder="例如 found_letter"></label>',button('取消','close-modal')+button('创建','confirm-switch','primary'));}
 if(a==='confirm-switch'){const key=$('#switch-name').value.trim();if(!/^[a-zA-Z][a-zA-Z0-9_]{0,49}$/.test(key))throw Error('使用字母开头的英文、数字与下划线');closeDialog();mutate(()=>story.switches[key]=false);}
 if(a==='pick-asset')await showAssets(x.dataset.target);if(a==='shared-assets')await showAssets();
 if(a==='use-asset'){const target=assetTarget,src=x.dataset.src;closeDialog();mutate(()=>{if(target==='gallery')selected().gallery.push(src);else if(target.startsWith('phone.'))setPath(story.phone,target.slice(6),src);else setPath(selected(),target,src);});}
 if(a==='clear-media')mutate(()=>{const target=x.dataset.target;if(target.startsWith('phone.'))setPath(story.phone,target.slice(6),'');else setPath(selected(),target,'');});
 if(a==='remove-gallery')mutate(()=>selected().gallery.splice(Number(x.dataset.index),1));
 if(a==='asset-menu'){const refs=user?await api('assets/'+id+'/references'):trials.filter(p=>JSON.stringify(p.document).includes('/local-assets/'+id)).map(p=>({project_id:p.document.title,version_id:''}));dialog('素材引用',`<p>${refs.length} 处草稿 / 发布版本引用。隐藏后文件继续保留。</p>${refs.map(r=>`<p>${esc(r.project_id)} · ${r.version_id?'发布快照':'草稿'}</p>`).join('')}`,button('关闭','close-modal')+button('从素材库隐藏','hide-asset','','data-id="'+id+'"'));}
 if(a==='hide-asset'){if(user)await api('assets/'+id,{method:'DELETE'});else await hideTrialAsset(id);await showAssets(assetTarget);}
 if(a==='shared-characters')await showCharacters();
 if(a==='save-character'){if(!user){login();return;}await api('characters',{method:'POST',body:clone(selected())});toast('已保存独立共享人物');}
 if(a==='import-character'){const c=clone(libraryCharacters.find(c=>c.id===id));c.id=uid('character');closeDialog();mutate(()=>{story.characters.push(c);section='characters';selectedId=c.id;});}
 if(a==='new-shared-character'||a==='edit-shared-character'){const c=id?libraryCharacters.find(c=>c.id===id):{name:'',status:''};dialog('共享人物',`<label>姓名<input id="shared-name" value="${esc(c.name)}"></label><label>状态<input id="shared-status" value="${esc(c.status)}"></label>`,button('取消','close-modal')+button('保存','confirm-shared-character','primary',id?'data-id="'+id+'"':''));}
 if(a==='confirm-shared-character'){const old=id?libraryCharacters.find(c=>c.id===id):newItem('characters',blank());await api('characters'+(id?'/'+id:''),{method:id?'PUT':'POST',body:{...old,name:$('#shared-name').value,status:$('#shared-status').value}});await showCharacters();}
 if(a==='delete-shared-character'){dialog('删除共享人物','<p>作品中已经导入的副本不会受到影响。</p>',button('取消','close-modal')+button('删除','confirm-delete-character','danger','data-id="'+id+'"'));}
 if(a==='confirm-delete-character'){await api('characters/'+id,{method:'DELETE'});await showCharacters();}
 if(a==='validate'){const errors=validate(story);dialog('剧情与格式检查',errors.length?'<ul>'+errors.map(t=>'<li>'+esc(t)+'</li>').join('')+'</ul>':'<p>当前引用与结构检查通过。实际剧情路径仍需试玩验证。</p>');}
 if(a==='publish')await publishDialog();
 if(a==='publish-now'){if($('#optional-check').checked){const errors=validate(story);if(errors.length)throw Error(errors.join('；'));}x.disabled=true;try{const result=await api('projects/'+current.id+'/publish',{method:'POST',body:{revision:current.revision,failurePolicy:$('#failure-policy').value}});Object.assign(current,result);closeDialog();await publishDialog();toast('服务端发布完成');}catch(err){x.disabled=false;throw err;}}
 if(a==='toggle-online'){const result=await api('projects/'+current.id+'/state',{method:'POST',body:{online:!current.online}});Object.assign(current,result);await publishDialog();}
 if(a==='debug-setup')debugSetup();
 if(a==='debug-start'){const progress=initialProgress(story);for(const el of modal.querySelectorAll('[data-multi="test.read"]:checked')){progress.facts['message.read:'+el.value]=true;progress.read.push(el.value);}for(const el of modal.querySelectorAll('[data-multi="test.facts"]:checked')){progress.facts[el.value]=true;progress.dependencies.push(el.value.split(':').slice(1).join(':'));}for(const el of modal.querySelectorAll('[data-multi="test.unlocked"]:checked'))progress.unlocked.push(el.value);for(const el of modal.querySelectorAll('[data-multi="test.switch"]:checked'))progress.variables[el.value]=true;const page=$('#test-page').value;closeDialog();phone?.destroy();phone=null;mode='play';renderEditor(progress);if(page.startsWith('event:')){phone.page='home';phone.dispatch({type:'test.event',id:page.slice(6)});}else if(page.startsWith('photo:')){phone.navigate('photos');phone.openPhoto(page.slice(6));}else phone.navigate(page);}
 }catch(err){toast(err.message);}});
window.addEventListener('offline',()=>{if(current&&!current.trial&&!reader){frozen=true;saveMessage=dirty?'网络中断 · 内存中有未保存修改，在线编辑已停止':'网络中断 · 在线编辑已停止';renderStatus();}});
window.addEventListener('online',()=>{if(current&&!current.trial&&frozen){saveMessage='连接已恢复。请点击重试保存；修订冲突不会被覆盖。';renderStatus();}});
