async function boot(){try{try{await trialAssets();}catch{}const requestedLogin=routePath()==='/login';const read=routePath().match(/^\/read\/([^/]+)$/);if(read){reader=true;const data=await api('read/'+read[1]);data.document.replyNodes??=[];current=data;story=data.document;mode='reader';app.className='reader';app.innerHTML='<main id="phone-mount"></main>';let progress=localRead('pocket-reader-'+data.publicId,null);if(progress&&(!compatible(story,progress)||progress.version!==3)){app.innerHTML=`<main class="reader-error"><h2>새 버전이 있습니다</h2><p>저장된 진행 상황을 완전히 이어갈 수 없습니다. 기존 저장은 아직 삭제하지 않았습니다.</p>${button('처음부터 시작','reader-reset','primary')}</main>`;app.onclick=e=>{if(e.target.closest('[data-action="reader-reset"]')){progress=initialProgress(story);progress.releaseId=data.versionId;app.innerHTML='<main id="phone-mount"></main>';mountPhone(progress);}};return;}if(progress&&!story.phone.remember)progress.phoneUnlocked=false;if(progress){for(const n of story.notes)if(!n.remember&&progress.notePasswords[n.id])progress.notePasswords[n.id].ok=false;}progress??=initialProgress(story);progress.releaseId=data.versionId;mountPhone(progress);return;}
 trials.forEach(p=>p.document.replyNodes??=[]);const auth=await api('auth/me');user=auth.user;await reloadProjects();const route=routePath().match(/^\/studio\/projects\/(.+)$/),p=route&&(user?projects:trials).find(p=>p.id===route[1]);if(p)await openProject(p);else library();if(requestedLogin)login();
 }catch(e){app.innerHTML=`<main class="reader-error"><h1>${reader?'작품을 열 수 없습니다':'服务暂不可用'}</h1><p>${esc(e.message)}</p><a href="${routeHref('/studio')}">${reader?'돌아가기':'返回作品库'}</a></main>`;}}
boot();



// Pointer sorting handles cover mobile browsers without native HTML drag-and-drop.
let touchSort=null;
document.addEventListener('pointerdown',e=>{const handle=e.target.closest('[data-reorder-handle]'),item=handle?.closest('[draggable="true"]');if(!item||!canEdit())return;e.preventDefault();e.stopPropagation();dragged={id:item.dataset.id||item.dataset.appId,order:item.dataset.order||(item.dataset.appId?'apps':'collection'),kind:item.dataset.kind||section};touchSort={item,target:item,x:e.clientX,y:e.clientY,moved:false};handle.setPointerCapture?.(e.pointerId);item.classList.add('sorting');});
document.addEventListener('pointermove',e=>{if(!touchSort)return;e.preventDefault();if(Math.hypot(e.clientX-touchSort.x,e.clientY-touchSort.y)>8)touchSort.moved=true;const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[draggable="true"]');if(target&&((target.dataset.order||'collection')===(touchSort.item.dataset.order||'collection'))){touchSort.target.classList.remove('sort-target');touchSort.target=target;target.classList.add('sort-target');}});
document.addEventListener('pointerup',()=>{if(!touchSort)return;const {item,target,moved}=touchSort;touchSort=null;item.classList.remove('sorting');target.classList.remove('sort-target');if(moved&&target!==item)target.dispatchEvent(new Event('drop',{bubbles:true,cancelable:true}));else dragged=null;});
document.addEventListener('pointercancel',()=>{touchSort?.item.classList.remove('sorting');touchSort?.target.classList.remove('sort-target');touchSort=null;dragged=null;});
